CREATE TABLE UserGameAssessment(UserGameAssessmentID INTEGER PRIMARY KEY, UserGameRecordID INTEGER NOT NULL, DifficultyRating DECIMAL(3,2), BaseLengthHours DECIMAL(8,2), FullCompletionHours DECIMAL(8,2), PersonalRating DECIMAL(4,2), CuratedUserScore DECIMAL(4,2), FOREIGN KEY (UserGameRecordID) REFERENCES UserGameRecord(UserGameRecordID), UNIQUE(UserGameRecordID), CHECK((DifficultyRating BETWEEN 1 AND 5)), CHECK((BaseLengthHours >= 0)), CHECK((FullCompletionHours >= 0)), CHECK((PersonalRating BETWEEN 0 AND 10)), CHECK((CuratedUserScore BETWEEN 0 AND 10)));
